    [TrangThai] NVARCHAR(50) NOT NULL,
    CONSTRAINT [UQ_TAI_KHOAN_TenDangNhap] UNIQUE ([TenDangNhap]),
    CONSTRAINT [UQ_TAI_KHOAN_MaNV] UNIQUE ([MaNV]),
    CONSTRAINT [CK_TAI_KHOAN_1] CHECK ([MaKhoa] IS NULL OR [MaPhong] IS NULL)
