-- 15. NHAN_VIEN
CREATE TABLE [dbo].[NHAN_VIEN] (
    [MaNV] NVARCHAR(50) NOT NULL CONSTRAINT [PK_NHAN_VIEN] PRIMARY KEY,
    [HoTen] NVARCHAR(255) NOT NULL,
    [GioiTinh] NVARCHAR(50) NULL,
