);

-- 16. CHUNG_CHI_NHAN_VIEN
CREATE TABLE [dbo].[CHUNG_CHI_NHAN_VIEN] (
    [MaCC] NVARCHAR(50) NOT NULL CONSTRAINT [PK_CHUNG_CHI_NHAN_VIEN] PRIMARY KEY,
