    [GhiChu] NVARCHAR(MAX) NULL,
    CONSTRAINT [CK_CHUNG_CHI_NHAN_VIEN_1] CHECK ([HanChungChi] IS NULL OR [HanChungChi] >= [NgayCap])
);

-- 17. KHOA
CREATE TABLE [dbo].[KHOA] (
