    [GhiChu] NVARCHAR(MAX) NULL,
    CONSTRAINT [CK_BAO_TRI_THIET_BI_1] CHECK ([ChiPhi] >= 0),
    CONSTRAINT [CK_BAO_TRI_THIET_BI_2] CHECK ([NgayKetThuc] IS NULL OR [NgayKetThuc] >= [NgayBatDau])
);

