    [NgayLam] DATE NOT NULL,
    [MaCa] NVARCHAR(50) NOT NULL,
    CONSTRAINT [PK_CA_THEO_NGAY] PRIMARY KEY ([NgayLam], [MaCa]),
    CONSTRAINT [FK_CA_THEO_NGAY_CA_LAM] FOREIGN KEY ([MaCa]) REFERENCES [dbo].[CA_LAM]([MaCa])
);

