IF NOT EXISTS(SELECT 1 FROM dbo.TAI_KHOAN t JOIN dbo.NHAN_VIEN n ON n.MaNV=t.MaNV WHERE t.MaTK=@actor AND t.TrangThai=N''Đang hoạt động'' AND n.TrangThai=N''Đang làm việc'')
