(N''RHM_TT_MAXILLA_FX'',N''RHM_DV_MULTITRAUMA'',N''Một phương án khi bác sĩ xác định đúng tổn thương, phạm vi và đủ điều kiện; không tự thêm cùng các phương án khác.'',2),
