    CONSTRAINT [CK_CTL_1] CHECK ([SoTien]>0 AND [TinhChat] IN (N''Cộng'',N''Trừ'')),
    CONSTRAINT [CK_CTL_2] CHECK ([LoaiKhoan] IN (N''Phụ cấp'',N''Làm thêm giờ'',N''Tạm ứng'',N''Tiền phạt'',N''Điều chỉnh'')),
    CONSTRAINT [CK_CTL_3] CHECK (LEN(LTRIM(RTRIM([LyDo])))>0)
);';
 IF OBJECT_ID(N'dbo.PHU_TA_DICH_VU',N'U') IS NULL
 EXEC sys.sp_executesql N'CREATE TABLE [dbo].[PHU_TA_DICH_VU] (
    [MaPTDV] NVARCHAR(50) NOT NULL CONSTRAINT [PK_PHU_TA_DICH_VU] PRIMARY KEY,
    [MaDVThucHien] NVARCHAR(50) NOT NULL,
    [MaNV] NVARCHAR(50) NOT NULL,
    [TrangThai] NVARCHAR(50) NOT NULL,
    [GhiChu] NVARCHAR(500) NULL,
    CONSTRAINT [UQ_PHU_TA_DV] UNIQUE ([MaDVThucHien],[MaNV]),
    CONSTRAINT [CK_PHU_TA_DV_TT] CHECK ([TrangThai] IN (N''Đã xác nhận'',N''Hủy''))
);';
 IF OBJECT_ID(N'dbo.CHI_TIET_HOA_HONG_LUONG',N'U') IS NULL
 EXEC sys.sp_executesql N'CREATE TABLE [dbo].[CHI_TIET_HOA_HONG_LUONG] (
    [MaCTHH] NVARCHAR(50) NOT NULL CONSTRAINT [PK_CHI_TIET_HOA_HONG_LUONG] PRIMARY KEY,
    [MaBL] NVARCHAR(50) NOT NULL,
