    [TienHoaHong] AS (CAST(ROUND([GiaTriTinh]*[TyLe],2) AS DECIMAL(18,2))) PERSISTED,
    CONSTRAINT [CK_CTHH_1] CHECK ([GiaTriTinh]>=0 AND [TyLe] BETWEEN 0 AND 1),
    CONSTRAINT [CK_CTHH_2] CHECK ([VaiTroHoaHong] IN (N''Bác sĩ'',N''Phụ tá'')),
    CONSTRAINT [UQ_CTHH_Luong_DichVu] UNIQUE ([MaBL],[MaCTHD],[VaiTroHoaHong])
);';
 IF OBJECT_ID(N'dbo.LAM_THEM_GIO',N'U') IS NULL
