    CONSTRAINT [CK_LTG_3] CHECK (([TrangThai]=N''Đã duyệt'' AND [MaNVDuyet] IS NOT NULL AND [NgayDuyet] IS NOT NULL) OR [TrangThai]<>N''Đã duyệt'')
);';
 IF OBJECT_ID(N'dbo.NHAT_KY_DUYET_CHAM_CONG',N'U') IS NULL
 EXEC sys.sp_executesql N'CREATE TABLE [dbo].[NHAT_KY_DUYET_CHAM_CONG](
 MaNhatKy bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_NHAT_KY_DUYET_CHAM_CONG PRIMARY KEY,
 MaLLV nvarchar(50) NOT NULL, MaNV nvarchar(50) NOT NULL, NguoiThucHien nvarchar(50) NOT NULL,
