 GioVaoCu datetime2(0) NULL, GioRaCu datetime2(0) NULL, GioVaoMoi datetime2(0) NULL, GioRaMoi datetime2(0) NULL,
 CongCu decimal(4,2) NOT NULL,CongMoi decimal(4,2) NOT NULL,LyDo nvarchar(500) NOT NULL
);';
 IF COL_LENGTH(N'dbo.LICH_KHAM',N'MucDoNghiemTrong') IS NULL
