 IF OBJECT_ID(N'dbo.CK_LICH_KHAM_MucDoNghiemTrong') IS NULL
 EXEC sys.sp_executesql N'ALTER TABLE dbo.[LICH_KHAM] WITH CHECK ADD CONSTRAINT [CK_LICH_KHAM_MucDoNghiemTrong] CHECK(MucDoNghiemTrong IN(N''Thấp'',N''Trung bình'',N''Cao''));';
 IF OBJECT_ID(N'dbo.FK_LICH_KHAM_BacSiDuBi') IS NULL
