UNION ALL
SELECT N''BANG_LUONG'' AS TenBang,COUNT_BIG(*) AS SoDong FROM dbo.[BANG_LUONG]
UNION ALL
SELECT N''NHAT_KY_THAO_TAC'' AS TenBang,COUNT_BIG(*) AS SoDong FROM dbo.[NHAT_KY_THAO_TAC]
UNION ALL
SELECT N''CA_THEO_NGAY'' AS TenBang,COUNT_BIG(*) AS SoDong FROM dbo.[CA_THEO_NGAY]
UNION ALL
SELECT N''XAC_NHAN_DOI_LICH_KHAM'' AS TenBang,COUNT_BIG(*) AS SoDong FROM dbo.[XAC_NHAN_DOI_LICH_KHAM]
UNION ALL SELECT N''NGAY_NGHI_LE'',COUNT_BIG(*) FROM dbo.[NGAY_NGHI_LE]
UNION ALL SELECT N''CHAM_CONG'',COUNT_BIG(*) FROM dbo.[CHAM_CONG]
UNION ALL SELECT N''CHI_TIET_LUONG'',COUNT_BIG(*) FROM dbo.[CHI_TIET_LUONG]
UNION ALL SELECT N''PHU_TA_DICH_VU'',COUNT_BIG(*) FROM dbo.[PHU_TA_DICH_VU]
UNION ALL SELECT N''CHI_TIET_HOA_HONG_LUONG'',COUNT_BIG(*) FROM dbo.[CHI_TIET_HOA_HONG_LUONG]
UNION ALL SELECT N''LAM_THEM_GIO'',COUNT_BIG(*) FROM dbo.[LAM_THEM_GIO]
UNION ALL SELECT N''NHAT_KY_DUYET_CHAM_CONG'',COUNT_BIG(*) FROM dbo.[NHAT_KY_DUYET_CHAM_CONG];';
 EXEC sys.sp_executesql N'CREATE OR ALTER PROCEDURE dbo.usp_RHM_KiemTraDongBoV9 AS
BEGIN
 SET NOCOUNT ON;
 IF NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N''RHM.SqlV9.Version'' AND TRY_CONVERT(int,value)=9)
  THROW 52335,N''Chưa hoàn tất hợp nhất SQL V9; chạy toàn bộ QLBenhVienRangHamMat.sql.'',1;
 DECLARE @cols TABLE(T sysname,C sysname,Ty sysname,L smallint,P tinyint,S tinyint,N bit);
